SELECT * FROM (
	SELECT * FROM BOOKS ORDER BY VIEW_COUNT DESC
) WHERE ROWNUM <= 3


SELECT * FROM (
	SELECT * FROM BOOKS ORDER BY LIKE_COUNT DESC
) WHERE ROWNUM <= 3


SELECT * FROM (
	SELECT * FROM BOOKS ORDER BY CREATE_DATE DESC
) WHERE ROWNUM <= 3

SELECT * FROM (
    SELECT b.*, ROWNUM AS rnum FROM (
        SELECT bk.*
        FROM BOOKS bk
        WHERE bk.STATUS <> 1
          AND LOWER(bk.TITLE) LIKE '%' || LOWER(#{keyword}) || '%'
        ORDER BY bk.CREATE_DATE DESC
    ) b
    WHERE ROWNUM <= #{endRow}
)
WHERE rnum > #{startRow}

