WHERE BOOKS_ID = #{value}

UPDATE BOOKS
SET STATUS = 3
WHERE BOOKS_ID = #{value}

UPDATE BOOKS
SET VIEW_COUNT = VIEW_COUNT + 1
WHERE BOOKS_ID = #{value}

UPDATE BOOKS
SET LOAN_COUNT = LOAN_COUNT + 1
WHERE BOOKS_ID = #{value}

UPDATE BOOKS
SET LIKE_COUNT = LIKE_COUNT + 1
WHERE BOOKS_ID = #{value}

